def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    # Divider rows/columns are nearly all one color and form regularly spaced lines.
    for color in set(v for row in grid for v in row):
        rs = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.8 * w]
        cs = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.8 * h]
        if len(rs) < 2 or len(cs) < 2:
            continue
        if min(b-a for a,b in zip(rs,rs[1:])) <= 1 or min(b-a for a,b in zip(cs,cs[1:])) <= 1:
            continue
        score = (len(rs)+len(cs), min(b-a for a,b in zip(rs,rs[1:])) + min(b-a for a,b in zip(cs,cs[1:])))
        if best is None or score > best[0]:
            best = (score, color, rs, cs)
    if best is None:
        raise ValueError('divider grid not found')
    _, line, rs, cs = best
    bg = Counter(v for row in grid for v in row if v != line).most_common(1)[0][0]
    cells = []
    for r0, r1 in zip(rs, rs[1:]):
        row = []
        for c0, c1 in zip(cs, cs[1:]):
            a,b,c,d = grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]
            row.append(a if a == b == c == d and a != line else bg)
        cells.append(row)
    marks = [(r,c) for r,row in enumerate(cells) for c,v in enumerate(row) if v != bg]
    if not marks:
        return [[bg]]
    r0,r1 = min(r for r,c in marks), max(r for r,c in marks)
    c0,c1 = min(c for r,c in marks), max(c for r,c in marks)
    return [row[c0:c1+1] for row in cells[r0:r1+1]]
